// P2 Learn: the few simulator formulas the concept demos need, written to match the backend engine exactly.
// This file is pure (no imports) and is checked number-for-number against docs/contracts/learn-fixtures.json, which is
// generated by running the REAL simulator (see tests/p2-learn-model.test.cjs and `pnpm fixtures:learn` in the API).
// Every figure these functions give is a model estimate, never a measurement.

export const STATUS = { ok: 0.75, fail: 1 } as const;
export const REPLICATION_COST = 0.25; // a replica spends a quarter of a write's cost replaying it
export const BURST_SECONDS = 60; // bursts are modelled as one-minute spikes
export const SATURATION_CLAMP = 0.985; // the waiting formula is held here; past it a full-queue penalty is added
export const RTT_MS: Record<string, number> = { "us-east|eu-west": 75, "us-east|ap-south": 190, "eu-west|ap-south": 115 };
export const UNKNOWN_RTT_MS = 120;

export type Region = "us-east" | "eu-west" | "ap-south";
export const REGIONS: Record<Region, string> = { "us-east": "US East", "eu-west": "EU West", "ap-south": "Asia South" };

/** Capacity per replica (requests/s) and service time (ms) of the components the demos use. */
export const COMPONENT = {
  app: { capacity: 600, latency: 22 },
  db: { capacity: 1800, latency: 6 },
  replica: { capacity: 1800, latency: 6 },
} as const;
export const CDN_DEFAULT_HIT = 0.6;
export const CACHE_DEFAULT_HIT = 0.8;

export type Status = "idle" | "ok" | "warn" | "fail";
export const statusOf = (rho: number, peak: number): Status => (!(peak > 0) ? "idle" : rho >= STATUS.fail ? "fail" : rho >= STATUS.ok ? "warn" : "ok");

/** Parallel servers: each replica can serve capacity x service time / 1000 requests at once, at least one. */
export const serversOf = (capacity: number, latencyMs: number, replicas: number) => Math.max(1, Math.round((capacity * latencyMs) / 1000)) * replicas;

/** Expected wait in the queue (ms) for a component with the given utilization, service time and parallel servers. */
export function waitMs(rho: number, serviceMs: number, servers: number): number {
  if (!(rho > 0) || !(serviceMs > 0)) return 0;
  const rc = Math.min(rho, SATURATION_CLAMP);
  let wq = (serviceMs * Math.pow(rc, Math.sqrt(2 * (servers + 1)) - 1)) / (servers * (1 - rc));
  if (rho > SATURATION_CLAMP) wq += serviceMs * 25 * Math.min(1, (rho - SATURATION_CLAMP) / 0.15);
  return wq;
}

export type NodeStats = { peak: number; cap: number; rho: number; status: Status; S: number; Wq: number; T: number; servers: number };

/** One component under a given peak load (requests/s at the burst). */
export function nodeStats(peak: number, capacity: number, replicas: number, latencyMs: number): NodeStats {
  const cap = capacity * replicas;
  const rho = cap > 0 ? peak / cap : peak > 0 ? Infinity : 0;
  const servers = serversOf(capacity, latencyMs, replicas);
  const Wq = waitMs(rho, latencyMs, servers);
  return { peak, cap, rho, status: statusOf(rho, peak), S: latencyMs, Wq, T: latencyMs + Wq, servers };
}

/** Utilization demo: steady load times the burst multiplier, against replicas of one component. */
export function utilization(i: { rps: number; burst: number; replicas: number; capacity: number; latency: number }): NodeStats {
  return nodeStats(i.rps * i.burst, i.capacity, i.replicas, i.latency);
}

export type QueueState = "idle" | "clear" | "absorbing" | "growing";
export type QueueStats = { arrival: number; peakArrival: number; drain: number; backlog: number; lag: number; overflow: number; state: QueueState };

/** Queue demo: writes arrive, workers drain. `drain` is the workers' combined rate (requests/s). */
export function queue(i: { rps: number; burst: number; drain: number; maxDepth: number; durationMin: number }): QueueStats {
  const arrival = i.rps,
    peakArrival = i.rps * i.burst,
    D = i.durationMin * 60;
  let backlog = 0,
    lag = 0,
    overflow = 0,
    state: QueueState = "clear";
  if (!(arrival > 0)) state = "idle";
  else if (i.drain < arrival) {
    backlog = (arrival - i.drain) * D;
    lag = i.drain > 0 ? backlog / i.drain : Infinity;
    state = "growing";
    overflow = Math.max(0, backlog - i.maxDepth) / (arrival * D);
  } else if (i.drain < peakArrival) {
    backlog = (peakArrival - i.drain) * BURST_SECONDS;
    lag = backlog / i.drain;
    state = "absorbing";
  }
  return { arrival, peakArrival, drain: i.drain, backlog, lag, overflow: Math.min(1, overflow), state };
}

export const WORKER_CAPACITY = 250; // requests/s per worker replica

// --- Percentiles: the engine reads p50/p95/p99 from a mixture of lognormal curves. ---
const phi = (z: number) => {
  const x = Math.abs(z) / Math.SQRT2,
    t = 1 / (1 + 0.3275911 * x);
  const y = 1 - ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-x * x);
  return z >= 0 ? (1 + y) / 2 : (1 - y) / 2;
};
type Curve = { p: number; mu: number; s: number };
const curve = (p: number, m: number, v: number): Curve => {
  const mean = Math.max(m, 0.05);
  const s2 = Math.log(1 + Math.max(v, 1e-6) / (mean * mean));
  return { p, mu: Math.log(mean) - s2 / 2, s: Math.sqrt(Math.max(s2, 1e-6)) };
};
const cdf = (curves: Curve[], x: number) => {
  const lx = Math.log(x);
  let F = 0;
  for (const c of curves) F += c.p * phi((lx - c.mu) / c.s);
  return F;
};
function quantile(curves: Curve[], q: number) {
  let lo = Math.log(0.05),
    hi = Math.log(1e7);
  for (let i = 0; i < 48; i++) {
    const mid = (lo + hi) / 2;
    if (cdf(curves, Math.exp(mid)) < q) lo = mid;
    else hi = mid;
  }
  return Math.exp((lo + hi) / 2);
}

/** Percentile demo: a share of requests take the slow path (mean `slow` ms), the rest the fast one (mean `fast` ms). */
export function percentiles(i: { fast: number; slow: number; share: number }): { p50: number; p95: number; p99: number } {
  const part = (p: number, m: number) => curve(p, m, Math.pow(0.35 * m, 2));
  const curves = [part(1 - i.share, i.fast), part(i.share, i.slow)].filter((c) => c.p > 0);
  return { p50: quantile(curves, 0.5), p95: quantile(curves, 0.95), p99: quantile(curves, 0.99) };
}

// --- Demos built on a single downstream component. The app tier in front is assumed not to be the limit. ---
const split = (rps: number, readRatio: number) => ({ reads: rps * readRatio, writes: rps * (1 - readRatio) });

/** Caching: reads that miss the cache reach the database, and every write does. */
export function caching(i: { rps: number; readRatio: number; hit: number; burst: number }) {
  const { reads, writes } = split(i.rps, i.readRatio);
  const dbReads = reads * (1 - i.hit);
  return { dbReads, dbWrites: writes, db: nodeStats((dbReads + writes) * i.burst, COMPONENT.db.capacity, 1, COMPONENT.db.latency) };
}

/** Read replicas: the primary and its replicas share the reads; every replica also replays the primary's writes. */
export function replicas(i: { rps: number; readRatio: number; replicas: number; burst: number }) {
  const { reads, writes } = split(i.rps, i.readRatio);
  const each = reads / (i.replicas + 1);
  const primary = nodeStats((each + writes) * i.burst, COMPONENT.db.capacity, 1, COMPONENT.db.latency);
  // An overloaded primary sheds work, which also shrinks what it replays.
  const kept = primary.rho > 1 ? 1 / primary.rho : 1;
  const replayed = writes * kept * REPLICATION_COST;
  const replica = i.replicas > 0 ? nodeStats(each * i.burst + replayed, COMPONENT.replica.capacity, 1, COMPONENT.replica.latency) : null;
  return { readsEach: each, primary, replica, replayed };
}

/** Load balancing: a balancer spreads the load evenly over identical servers. */
export function loadBalancing(i: { rps: number; servers: number; burst: number }) {
  const each = i.rps / i.servers;
  return { perServer: each, server: nodeStats(each * i.burst, COMPONENT.app.capacity, 1, COMPONENT.app.latency) };
}

/** CDNs: cacheable reads are answered at the edge, so only misses and writes reach the origin. */
export function cdn(i: { rps: number; readRatio: number; hit: number; burst: number }) {
  const { reads, writes } = split(i.rps, i.readRatio);
  const originReads = reads * (1 - i.hit);
  return { originReads, originWrites: writes, origin: nodeStats((originReads + writes) * i.burst, COMPONENT.app.capacity, 8, COMPONENT.app.latency) };
}

/** Regions: the round trip added when a request crosses regions. */
export function roundTripMs(a: Region | null | undefined, b: Region | null | undefined): number {
  if (!a || !b || a === b) return 0;
  return RTT_MS[a + "|" + b] || RTT_MS[b + "|" + a] || UNKNOWN_RTT_MS;
}
